<script lang="ts" setup>import { reactive, ref, watch } from "vue"import RLVFormField from "@rimelight/ui/components/vue/RLVFormField.vue"import RLVInput from "@rimelight/ui/components/vue/RLVInput.vue"import RLVButton from "@rimelight/ui/components/vue/RLVButton.vue"import { useAuth } from "@/composables/auth/useAuth"import { authClient } from "@/auth/auth-client"const { user } = useAuth()const profileState = reactive({  name: "",  image: ""})watch(  user,  (newUser) => {    if (newUser) {      profileState.name = newUser.name      profileState.image = newUser.image || ""    }  },  { immediate: true })const isUpdatingProfile = ref(false)async function updateProfile(e: Event) {  e.preventDefault()  isUpdatingProfile.value = true  const { error } = await authClient.updateUser({    name: profileState.name,    image: profileState.image || undefined  })  if (error) {    alert("Profile Update Failed: " + error.message)  } else {    alert("Profile Updated: Your profile details have been saved.")  }  isUpdatingProfile.value = false}const emailState = reactive({ newEmail: "" })const isUpdatingEmail = ref(false)async function updateEmail(e: Event) {  e.preventDefault()  isUpdatingEmail.value = true  const { error } = await authClient.changeEmail({    newEmail: emailState.newEmail,    callbackURL: "/dashboard"  })  if (error) {    alert("Email Update Failed: " + error.message)  } else {    alert("Email Update Scheduled: Please check your inbox to verify.")    emailState.newEmail = ""  }  isUpdatingEmail.value = false}const passwordState = reactive({  current: "",  newPassword: ""})const isUpdatingPassword = ref(false)async function updatePassword(e: Event) {  e.preventDefault()  if (!passwordState.current || !passwordState.newPassword) return  isUpdatingPassword.value = true  const { error } = await authClient.changePassword({    currentPassword: passwordState.current,    newPassword: passwordState.newPassword,    revokeOtherSessions: true  })  if (error) {    alert("Password Update Failed: " + error.message)  } else {    alert("Password Updated successfully.")    passwordState.current = ""    passwordState.newPassword = ""  }  isUpdatingPassword.value = false}const isDeleting = ref(false)async function deleteAccount() {  const isConfirmed = confirm(    "Delete your account? This action is irreversible. All your data will be permanently removed."  )  if (!isConfirmed) return  isDeleting.value = true  const { error } = await authClient.deleteUser({    callbackURL: "/goodbye"  })  if (error) {    if (error.code === "FRESH_SESSION_REQUIRED") {      alert("Security Check Required: Please log out and log back in to delete your account.")    } else {      alert("Deletion Failed: " + error.message)    }  }  isDeleting.value = false}</script><template>  <div class="flex flex-col gap-8">    <!-- Profile Card -->    <div      class="p-6 bg-white dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-2xl space-y-4"    >      <div>        <h3 class="text-lg font-bold text-neutral-900 dark:text-white">Profile Details</h3>        <p class="text-xs text-neutral-500">Manage your public profile information.</p>      </div>      <form @submit="updateProfile" class="flex max-w-sm flex-col gap-4">        <RLVFormField label="Display Name">          <RLVInput v-model="profileState.name" leadingIcon="i-lucide-user" class="w-full" />        </RLVFormField>        <RLVFormField label="Avatar URL">          <RLVInput v-model="profileState.image" leadingIcon="i-lucide-image" class="w-full" />        </RLVFormField>        <RLVButton :loading="isUpdatingProfile" class="w-fit" type="submit">          Save Changes        </RLVButton>      </form>    </div>    <!-- Email Card -->    <div      class="p-6 bg-white dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-2xl space-y-4"    >      <div>        <h3 class="text-lg font-bold text-neutral-900 dark:text-white">Email Address</h3>        <p class="text-xs text-neutral-500">          Update your email address. You will need to verify the new email.        </p>      </div>      <div        class="flex flex-row items-center gap-1.5 text-sm text-neutral-700 dark:text-neutral-300"      >        Current email:        <span class="font-medium">{{ user?.email }}</span>        <span v-if="user?.emailVerified" class="text-xs text-green-500 font-bold">(Verified)</span>        <span v-else class="text-xs text-amber-500 font-bold">(Unverified)</span>      </div>      <form @submit="updateEmail" class="flex max-w-sm flex-col gap-4">        <RLVFormField label="New Email">          <RLVInput            v-model="emailState.newEmail"            type="email"            leadingIcon="i-lucide-mail"            placeholder="email@domain.com"            class="w-full"          />        </RLVFormField>        <RLVButton :loading="isUpdatingEmail" class="w-fit" type="submit"> Update Email </RLVButton>      </form>    </div>    <!-- Password Card -->    <div      class="p-6 bg-white dark:bg-neutral-950 border border-neutral-200 dark:border-neutral-800 rounded-2xl space-y-4"    >      <div>        <h3 class="text-lg font-bold text-neutral-900 dark:text-white">Password</h3>        <p class="text-xs text-neutral-500">          Confirm your current password before setting a new one.        </p>      </div>      <form @submit="updatePassword" class="flex max-w-sm flex-col gap-4">        <RLVFormField label="Current Password">          <RLVInput            v-model="passwordState.current"            type="password"            placeholder="••••••••"            class="w-full"          />        </RLVFormField>        <RLVFormField label="New Password">          <RLVInput            v-model="passwordState.newPassword"            type="password"            placeholder="••••••••"            class="w-full"          />        </RLVFormField>        <RLVButton :loading="isUpdatingPassword" class="w-fit" type="submit">          Update Password        </RLVButton>      </form>    </div>    <!-- Delete Account Card -->    <div      class="p-6 bg-red-50/50 dark:bg-red-950/20 border border-red-200 dark:border-red-900/50 rounded-2xl space-y-4"    >      <div>        <h3 class="text-lg font-bold text-red-700 dark:text-red-400">Delete Account</h3>        <p class="text-xs text-red-500/80">          No longer want to use our service? This action is not reversible.        </p>      </div>      <p class="text-sm text-neutral-700 dark:text-neutral-300">        This will schedule your account for deletion after 30 days and revoke all active sessions.        Signing back in at any point during this period will cancel the scheduling.      </p>      <RLVButton        :loading="isDeleting"        class="w-fit bg-red-600 hover:bg-red-700 text-white border-none"        @click="deleteAccount"      >        Delete Account      </RLVButton>    </div>  </div></template>